CREATE DATABASE IF NOT EXISTS sipro CHARACTER SET utf8mb4;
USE sipro;
CREATE TABLE users(id_user INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,email VARCHAR(100) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','agen','pembeli') NOT NULL DEFAULT 'pembeli');
CREATE TABLE properti(id_properti INT AUTO_INCREMENT PRIMARY KEY,id_agen INT NOT NULL,judul VARCHAR(150) NOT NULL,deskripsi TEXT,harga BIGINT NOT NULL,lokasi VARCHAR(100) NOT NULL,tipe ENUM('Rumah','Ruko','Tanah','Apartemen') NOT NULL,luas_tanah INT DEFAULT 0,luas_bangunan INT DEFAULT 0,kamar_tidur INT DEFAULT 0,kamar_mandi INT DEFAULT 0,status ENUM('Tersedia','Dalam Negosiasi','Terjual') NOT NULL DEFAULT 'Tersedia',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_agen) REFERENCES users(id_user));
CREATE TABLE foto_properti(id_foto INT AUTO_INCREMENT PRIMARY KEY,id_properti INT NOT NULL,nama_file VARCHAR(100) NOT NULL,FOREIGN KEY(id_properti) REFERENCES properti(id_properti) ON DELETE CASCADE);
CREATE TABLE permintaan(id_permintaan INT AUTO_INCREMENT PRIMARY KEY,id_user INT NOT NULL,id_properti INT NOT NULL,tanggal TIMESTAMP DEFAULT CURRENT_TIMESTAMP,pesan TEXT,status ENUM('Diajukan','Dihubungi','Survei Dijadwalkan','Selesai') NOT NULL DEFAULT 'Diajukan',FOREIGN KEY(id_user) REFERENCES users(id_user),FOREIGN KEY(id_properti) REFERENCES properti(id_properti) ON DELETE CASCADE);
CREATE TABLE jadwal_survei(id_survei INT AUTO_INCREMENT PRIMARY KEY,id_permintaan INT NOT NULL,tanggal_survei DATETIME NOT NULL,status_survei ENUM('Menunggu','Dikonfirmasi','Selesai','Dibatalkan') NOT NULL DEFAULT 'Menunggu',FOREIGN KEY(id_permintaan) REFERENCES permintaan(id_permintaan) ON DELETE CASCADE);
CREATE TABLE tindak_lanjut(id_tindak_lanjut INT AUTO_INCREMENT PRIMARY KEY,id_permintaan INT NOT NULL,id_agen INT NOT NULL,catatan TEXT NOT NULL,tanggal TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_permintaan) REFERENCES permintaan(id_permintaan) ON DELETE CASCADE,FOREIGN KEY(id_agen) REFERENCES users(id_user));
CREATE TABLE transaksi_penjualan(id_transaksi INT AUTO_INCREMENT PRIMARY KEY,id_properti INT NOT NULL,id_pembeli INT NOT NULL,tanggal_transaksi DATE NOT NULL,harga_final BIGINT NOT NULL,status ENUM('Proses','Selesai','Batal') NOT NULL DEFAULT 'Selesai',FOREIGN KEY(id_properti) REFERENCES properti(id_properti),FOREIGN KEY(id_pembeli) REFERENCES users(id_user));
